    reg [7:0] r0, r1, r2, r3, r4, r5, r6, r7;
    wire [7:0] qs [0:7];
    genvar i;
    // The register chain - a long inline chain of registers, connected
    // together in an array.
    always @(negedge clk) begin
        if (reset) begin
            r0 <= 8'h34; r1 <= 8'h34; r2 <= 8'h34; r3 <= 8'h34; r4 <= 8'h34; r5 <= 8'h34; r6 <= 8'h34; r7 <= 8'h34;
        end else begin
            r0 <= d;
            r1 <= r0;
            r2 <= r1;
            r3 <= r2;
            r4 <= r3;
            r5 <= r4;
            r6 <= r5;
            r7 <= r6;
